import{z as B,x as d,o as n,c as A,q as o,j as t,D as E,d as r,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"美元主导与国际货币","description":"","frontmatter":{"title":"美元主导与国际货币","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dollar-dominance.md","filePath":"econ/dollar-dominance.md","lastUpdated":1791063341000}'),p={name:"econ/dollar-dominance.md"};function h(m,a,c,u,f,D){const i=d("Mermaid");return n(),A("div",null,[a[2]||(a[2]=o('<h1 id="美元主导与国际货币" tabindex="-1">美元主导与国际货币 <a class="header-anchor" href="#美元主导与国际货币" aria-label="Permalink to &quot;美元主导与国际货币&quot;">​</a></h1><div class="epigraph"><p>全球安全资产与贸易计价仍高度集中在美元。这是网络与政策背书，不是单一货币数量方程的世界版。</p><footer>—— Gopinath 等的计价货币；Rey 的全球金融周期；Eichengreen 对国际货币史</footer></div><p><a href="/econ/cbdc">上一课</a>把公共数字负债留在国内设计。本课收束「动态宏观与异质性」：跨境时，美元负债与美联储互换线才是真正的全球地板。下一课换到货币银行，问<a href="/econ/why-intermediaries">金融中介的功能</a>：中介为何存在。公司金融进阶另起课程，首课是<a href="/econ/npv-irr-pitfalls">NPV 与 IRR 的陷阱</a>，不在这里写治理。开放宏观的危机与互换线，贸易课序后半会再展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Rey：在资本流动下，中心国家的货币政策经风险承担渠道变成全球金融周期，浮动汇率不能完全绝缘。Gopinath：贸易以美元计价，汇率传递变弱，美国的名义冲击变成别人的实际冲击。若把「国际货币」写成铸币税口号，会漏掉：主导是发票、银行跨境负债、储备和安全资产便利收益（Du–Im–Schreger 一类）的捆绑。</p><p>缺口是给后课贸易与危机一张结构图，而不是再推一遍 NK 小国。</p><p><span class="marginnote">Gourinchas 的美元特权讨论。Maggiori, Neiman and Schreger 的货币选择。Miranda-Agrippino and Rey 的全球因子。</span></p><p><span class="marginnote">计价为什么削弱传递：若合同写明以美元结算，美元兑当地货币贬 10%，出口商收到的美元一分不少，商品标价也不必动——汇率波动进不了价签，只在换算成本币利润时才被感觉到。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层：计价（贸易与金融合同）、中介（全球银行的美元负债）、官方（储备、互换）。冲击：美联储加息 → 全球 \\(\\phi\\) 收紧 → 新兴市场信用与汇率。政策：宏观审慎、资本流动管理、互换线（后课）。与主导课：美国财政–货币安排通过安全资产供给外溢。</p>',10)),(n(),t(s,null,{default:E(()=>[l(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E7%BE%8E%E5%85%83%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20PASS%5B%22%E4%BC%A0%E9%80%92%E5%87%8F%E5%BC%B1%22%5D%0A%20%20BANK%5B%22%E8%B7%A8%E5%A2%83%E7%BE%8E%E5%85%83%E8%B4%9F%E5%80%BA%22%5D%20--%3E%20GFC%5B%22%E5%85%A8%E7%90%83%E9%87%91%E8%9E%8D%E5%91%A8%E6%9C%9F%22%5D%0A%20%20RES%5B%22%E5%82%A8%E5%A4%87%E4%B8%8E%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20FLOOR%5B%22%E5%AE%98%E6%96%B9%E5%9C%B0%E6%9D%BF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"网络外部性：别人用美元开票，你也用，以匹配成本。银行侧：欧洲银行借美元、买美元资产，美元融资紧张时全球信用收缩（Bruno–Shin）。官方侧：美债便利收益使美国能以更低 \\(r\\) 负债，同时输出安全资产短缺的另一面。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"便利收益可以翻译成『占着舒服位置的隐性租金』：美债除了利息，还额外提供全球公认的安全与流动性，投资者愿意为此接受略低的收益，这份折价反过来变成美国财政部账上的便宜钱。")],-1)),a[6]||(a[6]=e("p",null,"「为什么美元主导难以被替代」可以画成一个自我强化的轮子：",-1)),(n(),t(s,null,{default:E(()=>[l(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20USE%5B%22%E6%9B%B4%E5%A4%9A%E4%BA%A4%E6%98%93%E7%94%A8%E7%BE%8E%E5%85%83%E5%BC%80%E7%A5%A8%22%5D%20--%3E%20LIQ%5B%22%E7%BE%8E%E5%85%83%E8%AE%A1%E4%BB%B7%E5%B8%82%E5%9C%BA%E6%B5%81%E5%8A%A8%E6%80%A7%E6%9B%B4%E6%B7%B1%22%5D%0A%20%20LIQ%20--%3E%20CHEAP%5B%22%E8%9E%8D%E8%B5%84%E4%B8%8E%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20CHEAP%20--%3E%20BACK%5B%22%E6%9B%B4%E5%A4%9A%E4%BA%A4%E6%98%93%E6%94%B9%E7%94%A8%E7%BE%8E%E5%85%83%22%5D%0A%20%20RESV%5B%22%E5%AE%98%E6%96%B9%E5%82%A8%E5%A4%87%E5%81%8F%E5%A5%BD%E5%AE%89%E5%85%A8%E7%BE%8E%E5%85%83%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20LIQ%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">常见误区：以为最大经济体的货币自动成为国际货币。美国经济总量在 19 世纪 70 年代已超过英国，英镑的主导地位却延续到两次大战之间——惯性来自已建成的清算网络与制度安排，换帅比经济反超慢几十年。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写欧元区制度史（贸易课欧元区危机）。不把去美元化写成已完成事实。CBDC 跨境结算是实验，不替代互换网络。后课默认：小国模型要声明发票货币与美元负债敞口。动态宏观补层在此封口；下一课程从<a href="/econ/why-intermediaries">金融中介的功能</a>起，企业项目估值另起一门，不在货币银行之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>美元主导是计价、中介与官方地板的捆绑。</li><li>浮动汇率不能取消 Rey 意义上的全球周期。</li><li>出处：Rey 全球金融周期；Gopinath 计价；Bruno–Shin 美元信贷。</li></ul>',5))])}const S=B(p,[["render",h]]);export{C as __pageData,S as default};
